const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Carichiamo il file .env dal percorso specifico
const envPath = path.resolve(__dirname, '../dab-project/.env');
dotenv.config({ path: envPath });

// Recuperiamo le variabili d'ambiente
const MONGO_URI = process.env.MONGO_URI;
// Uso 'throne_and_liberty' come fallback se non è definito nel .env
const DB_NAME = process.env.MONGO_DB_NAME || 'throne_and_liberty';
const COLLECTION_NAME = 'skill_cores';

// Controllo per evitare esecuzioni se l'URI non è presente
if (!MONGO_URI) {
    console.error(`❌ Errore: MONGO_URI non trovato. Assicurati che il file .env esista in ${envPath} e contenga MONGO_URI.`);
    process.exit(1);
}

